Here's a JavaScript function that sorts the books according to the given conditions:

```javascript
/**
 * Sorts an array of book titles based on the following conditions:
 * 1. Numbers come before letters in the sorted result.
 * 2. If two books have the same starting letter, sort them based on their lengths in descending order.
 * 3. If two books have the same starting letter and length, sort them based on their ASCII values in descending order.
 * 4. If two books have the same starting letter, length, and ASCII value, keep the original order of those books in the sorted result.
 *
 * @param {string[]} books - The array of book titles.
 * @returns {string[]} A new array containing the books sorted according to the given conditions.
 */
function sortBooks(books) {
    // Use the Array.prototype.sort() method to sort the books array
    return books.sort((a, b) => {
        // Check if the first character of both books is a digit
        const isFirstDigitA = !isNaN(a[0]);
        const isFirstDigitB = !isNaN(b[0]);

        // If both books are numbers, compare them directly
        if (isFirstDigitA && isFirstDigitB) {
            return parseInt(a) - parseInt(b);
        }

        // If the first book is a number and the second is a letter, or vice versa, swap their positions
        if (isFirstDigitA) {
            return -1;
        } else if (isFirstDigitB) {
            return 1;
        }

        // If both books are letters, compare their first characters
        if (a[0] < b[0]) {
            return -1;
        } else if (a[0] > b[0]) {
            return 1;
        }

        // If both books have the same first character, compare their lengths
        if (a.length < b.length) {
            return -1;
        } else if (a.length > b.length) {
            return 1;
        }

        // If both books have the same first character and length, compare their ASCII values
        if (a.charCodeAt(0) < b.charCodeAt(0)) {
            return -1;
        } else if (a.charCodeAt(0) > b.charCodeAt(0)) {
            return 1;
        }

        // If all comparisons are equal, keep the original order
        return 0;
    });
}

